package app.noir.mobile;
import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;
public final class TasteCodeTest {
    static final String SHARED_VECTOR="AQ1Ob2lyINmE2YrZhNmJAgACB-UAAbI5AwABsjkKAAIH5QkAFP2yCA";
    TasteCode.Card card(int... scores){List<TasteCode.Rating> r=new ArrayList<>();for(int i=0;i<scores.length;i++)r.add(new TasteCode.Rating(i+1,scores[i]));return TasteCode.create("",new int[0],r,null);}
    @Test public void vectorAndRoundTrip(){TasteCode.Card source=TasteCode.create("Noir ليلى",new int[]{133093,111161},Arrays.asList(new TasteCode.Rating(1375666,8),new TasteCode.Rating(111161,10),new TasteCode.Rating(133093,9)),null);assertEquals(SHARED_VECTOR,TasteCode.encode(source));TasteCode.Card d=TasteCode.decode(TasteCode.PREFIX+SHARED_VECTOR);assertNotNull(d);assertEquals(source.name,d.name);assertArrayEquals(source.favorites,d.favorites);assertEquals(3,d.ratings.length);assertEquals(10,d.ratings[0].rating10);assertEquals(SHARED_VECTOR,TasteCode.encode(d));}
    @Test public void malformedAndLimits(){for(String s:new String[]{null,"","%%%%","noir://other/"+SHARED_VECTOR,SHARED_VECTOR+"=",SHARED_VECTOR+"A",SHARED_VECTOR.substring(0,SHARED_VECTOR.length()-1),"AgAAAA","AQEAAA"})assertNull(s,TasteCode.decode(s));byte[] bytes=Base64.getUrlDecoder().decode(SHARED_VECTOR);bytes[1]=65;assertNull(TasteCode.decode(Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)));bytes=Base64.getUrlDecoder().decode(SHARED_VECTOR);bytes[bytes.length-1]=11;assertNull(TasteCode.decode(Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)));bytes=Base64.getUrlDecoder().decode(SHARED_VECTOR);bytes[2]=(byte)255;assertNull(TasteCode.decode(Base64.getUrlEncoder().withoutPadding().encodeToString(bytes)));List<TasteCode.Rating> ratings=new ArrayList<>();for(int i=1;i<=100;i++)ratings.add(new TasteCode.Rating(i,8));TasteCode.Card full=TasteCode.create(String.join("",Collections.nCopies(100,"界")),new int[]{1,2,3,4,5},ratings,null);assertEquals(4,full.favorites.length);assertEquals(60,full.ratings.length);assertTrue(full.name.getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=64);assertNotNull(TasteCode.decode(TasteCode.link(full)));Random random=new Random(47);for(int i=0;i<300;i++){byte[] b=new byte[random.nextInt(400)];random.nextBytes(b);TasteCode.decode(Base64.getUrlEncoder().withoutPadding().encodeToString(b));}}
    @Test public void hiddenExcluded(){TasteCode.Card source=TasteCode.decode(SHARED_VECTOR);TasteCode.Card filtered=TasteCode.create(source.name,source.favorites,Arrays.asList(source.ratings),new HashSet<>(Arrays.asList(133093)));assertArrayEquals(new int[]{111161},filtered.favorites);assertEquals(2,filtered.ratings.length);assertNotNull(TasteCode.decode(TasteCode.link(filtered)));for(TasteCode.Rating r:filtered.ratings)assertNotEquals(133093,r.id);}
    @Test public void scoringAndFallback(){TasteCode.Card a=card(1,3,5,7,9);TasteCode.Match same=TasteCode.compare(a,a,null);assertEquals(Integer.valueOf(100),same.score);assertTrue(same.correlation);assertEquals(5,same.overlap);TasteCode.Match inverse=TasteCode.compare(a,card(9,7,5,3,1),null);assertEquals(Integer.valueOf(0),inverse.score);assertArrayEquals(new int[]{1,5,2,4},inverse.disagreements);TasteCode.Match flat=TasteCode.compare(card(8,8,8,8,8),card(8,8,8,8,8),null);assertEquals(Integer.valueOf(100),flat.score);assertFalse(flat.correlation);TasteCode.Card fa=TasteCode.create("a",new int[]{1,2},Collections.emptyList(),null),fb=TasteCode.create("b",new int[]{1,2},Collections.emptyList(),null);TasteCode.Match small=TasteCode.compare(fa,fb,null);assertEquals(Integer.valueOf(100),small.score);assertEquals(0,small.overlap);assertFalse(small.correlation);assertArrayEquals(new int[]{1,2},small.bothLoved);Map<Integer,String[]> genres=new HashMap<>();genres.put(1,new String[]{"Drama"});genres.put(2,new String[]{"Drama"});TasteCode.Match genre=TasteCode.compare(TasteCode.create("a",new int[0],Arrays.asList(new TasteCode.Rating(1,9)),null),TasteCode.create("b",new int[0],Arrays.asList(new TasteCode.Rating(2,9)),null),genres);assertEquals(Integer.valueOf(100),genre.score);assertNull(TasteCode.compare(card(),card(),null).score);}
    @Test public void qrIsLocalAndFitsFullCard(){List<TasteCode.Rating> ratings=new ArrayList<>();for(int i=1;i<=60;i++)ratings.add(new TasteCode.Rating(i*100001,10));QrCode qr=QrCode.encodeText(TasteCode.link(TasteCode.create("Noir ليلى",new int[]{1,2,3,4},ratings,null)),QrCode.Ecc.MEDIUM);assertTrue(qr.size>=21&&qr.size<=177);assertTrue(qr.getModule(0,0));assertFalse(qr.getModule(-1,-1));}
}
